import{_ as e,a as s,a3 as t,o as a}from"./chunks/framework.edeurCMZ.js";const k=JSON.parse('{"title":"LDAP TLS Certificate Validation","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/LDAPCertificateValidation.md","filePath":"devdoc/LDAPCertificateValidation.md","lastUpdated":1787329496000}'),n={name:"devdoc/LDAPCertificateValidation.md"};function r(o,i,l,h,d,p){return a(),s("div",null,[...i[0]||(i[0]=[t(`<h1 id="ldap-tls-certificate-validation" tabindex="-1">LDAP TLS Certificate Validation <a class="header-anchor" href="#ldap-tls-certificate-validation" aria-label="Permalink to &quot;LDAP TLS Certificate Validation&quot;">​</a></h1><p>This document describes how to enable TLS certificate validation for LDAPS connections in the HPCC Platform. By default, the platform connects to LDAPS endpoints without validating the server certificate. Enabling validation protects against Man-in-the-Middle (MITM) attacks on the connection between HPCC and the LDAP directory server.</p><hr><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>When the HPCC Platform connects to an LDAP server over LDAPS (port 636), TLS encrypts the connection. However, encryption alone does not guarantee you are talking to the correct server. Without certificate validation, an attacker positioned on the network path between HPCC and the directory server can impersonate the server, intercept credentials, and inject fabricated responses.</p><p>In enterprise deployments where Active Directory domain controllers span both cloud and on-premises sites, LDAPS traffic can cross WAN links or cloud interconnects. Certificate validation ensures the server on the other end is the legitimate directory server regardless of which network segment the connection traverses.</p><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Two attributes control TLS certificate validation in the LDAP configuration block:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ldapTLSValidation</code></td><td>string</td><td><code>disabled</code></td><td>Validation mode: <code>disabled</code>, <code>permissive</code>, or <code>strict</code></td></tr><tr><td><code>ldapCACertFile</code></td><td>string</td><td><em>(empty)</em></td><td>Path to CA certificate file. Strongly recommended when <code>ldapTLSValidation</code> is <code>strict</code> or <code>permissive</code>. If omitted, the system trust store is used silently — no warning at startup. If the connection fails, the error message will suggest setting this. Requires the <code>hpcc</code> user to have read access to the system trust store (typically <code>/etc/ssl/certs/</code>)</td></tr></tbody></table><h3 id="validation-modes" tabindex="-1">Validation Modes <a class="header-anchor" href="#validation-modes" aria-label="Permalink to &quot;Validation Modes&quot;">​</a></h3><p><strong><code>disabled</code></strong> <em>(default)</em><br> Certificate validation is not performed. The platform accepts any certificate presented by the server. This preserves backward-compatible behaviour.</p><p><strong><code>permissive</code></strong><br> Certificate validation is attempted. If validation cannot be enabled, an error is logged and the connection proceeds. Use this mode when transitioning to full validation and you need to diagnose issues without hard-failing.</p><p><strong><code>strict</code></strong><br> Certificate validation is required. If validation cannot be enabled, the platform throws and will not start. Use this mode in production.</p><h3 id="example-configuration-environment-xml" tabindex="-1">Example Configuration (environment.xml) <a class="header-anchor" href="#example-configuration-environment-xml" aria-label="Permalink to &quot;Example Configuration (environment.xml)&quot;">​</a></h3><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ldap</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ldapTLSValidation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;strict&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">      ldapCACertFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/hpcc/certs/ldap-ca.crt&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ... /&gt;</span></span></code></pre></div><h3 id="example-configuration-helm-values" tabindex="-1">Example Configuration (Helm values) <a class="header-anchor" href="#example-configuration-helm-values" aria-label="Permalink to &quot;Example Configuration (Helm values)&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ldap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ldapTLSValidation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;strict&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ldapCACertFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/hpcc/certs/ldap-ca.crt&quot;</span></span></code></pre></div><hr><h2 id="certificate-requirements" tabindex="-1">Certificate Requirements <a class="header-anchor" href="#certificate-requirements" aria-label="Permalink to &quot;Certificate Requirements&quot;">​</a></h2><h3 id="ldap-connection-pool" tabindex="-1">LDAP Connection Pool <a class="header-anchor" href="#ldap-connection-pool" aria-label="Permalink to &quot;LDAP Connection Pool&quot;">​</a></h3><p>The HPCC Platform maintains a pool of persistent LDAP connections to support concurrent requests. The pool may hold connections to multiple LDAP hosts (configured via <code>ldapAddress</code> as a comma-separated list of replicas or domain controllers) that all share the same TLS configuration.</p><p>Because the CA certificate file (<code>ldapCACertFile</code>) is loaded into a per-connection TLS context for every connection in the pool, <strong>all servers in the pool must present certificates that chain to a CA included in that file</strong> (or in the system trust store if no file is specified).</p><p>This is not a practical constraint for well-formed deployments:</p><ul><li><strong>Active Directory</strong>: All domain controllers in a domain receive certificates from the same internal enterprise CA. A single CA cert file covers every DC in the pool.</li><li><strong>OpenLDAP replicas</strong>: Replicas are typically provisioned from the same PKI, so the same CA cert applies to all.</li><li><strong>Mixed CAs</strong>: If pool members genuinely use certificates from different CAs, combine the required CA certificates into a single PEM bundle file and set <code>ldapCACertFile</code> to that bundle.</li></ul><blockquote><p><strong>Note:</strong> Each server in the pool may serve its own distinct leaf certificate — they do not all need to be identical. What matters is that every leaf certificate chains to a CA present in the configured file.</p></blockquote><hr><h3 id="active-directory-enterprise-ca-pool-configuration" tabindex="-1">Active Directory / Enterprise CA Pool Configuration <a class="header-anchor" href="#active-directory-enterprise-ca-pool-configuration" aria-label="Permalink to &quot;Active Directory / Enterprise CA Pool Configuration&quot;">​</a></h3><p>This section covers the correct way to configure TLS certificate validation for a pool of LDAP servers backed by a proper enterprise Certificate Authority — Active Directory domain controllers or OpenLDAP replicas in an organisation with an internal PKI.</p><h4 id="how-enterprise-pki-handles-pool-certs-automatically" tabindex="-1">How enterprise PKI handles pool certs automatically <a class="header-anchor" href="#how-enterprise-pki-handles-pool-certs-automatically" aria-label="Permalink to &quot;How enterprise PKI handles pool certs automatically&quot;">​</a></h4><p>With Active Directory, each domain controller is automatically issued a TLS certificate by the domain&#39;s enterprise CA (typically Microsoft Active Directory Certificate Services, AD CS). These certificates are provisioned without manual intervention and have the following properties that make pool validation straightforward:</p><ul><li>The DC&#39;s fully-qualified domain name (e.g. <code>dc1.corp.example.com</code>) is included as a Subject Alternative Name (SAN) in its certificate</li><li>All DC certificates are signed by the same enterprise CA root</li><li>The CA certificate is distributed automatically to all domain-joined machines via Group Policy</li></ul><p>The result: every server in the pool presents a valid, individually-identified certificate. OpenLDAP verifies each connection independently — when HPCC connects to <code>dc1.corp.example.com</code> the cert presented includes that hostname in its SAN, and when it connects to <code>dc2.corp.example.com</code> that cert includes its own hostname. No special handling is needed beyond pointing HPCC at the right CA cert.</p><p>For OpenLDAP replicas managed through an internal PKI the same applies: each replica is issued its own cert from the internal CA, with its own hostname in the SAN.</p><h4 id="use-hostnames-not-ip-addresses" tabindex="-1">Use hostnames, not IP addresses <a class="header-anchor" href="#use-hostnames-not-ip-addresses" aria-label="Permalink to &quot;Use hostnames, not IP addresses&quot;">​</a></h4><p>In enterprise deployments always configure pool members by <strong>hostname</strong>, not IP address. This matters for two reasons:</p><ol><li><p><strong>Hostname verification</strong>: Enterprise server certs list the server&#39;s DNS name as the SAN, not its IP. If HPCC connects by IP (<code>10.1.2.3</code>) but the cert only lists <code>dc1.corp.example.com</code>, validation fails even though it is the correct server.</p></li><li><p><strong>Stability</strong>: Server IPs can change (VM migration, re-provisioning). Hostnames and their certs remain valid as long as DNS is updated.</p></li></ol><p>In <code>environment.xml</code>, configure the <code>Hardware/Computer</code> entries with fully-qualified hostnames:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Hardware</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Computer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc1&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> netAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc1.corp.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Computer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc2&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> netAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc2.corp.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Computer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc3&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> netAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc3.corp.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Hardware</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">LDAPServerProcess</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Instance</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc1&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;s1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Instance</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc2&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;s2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Instance</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dc3&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;s3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">LDAPServerProcess</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>This produces <code>ldapAddress=&quot;dc1.corp.example.com|dc2.corp.example.com|dc3.corp.example.com&quot;</code> in the generated configuration, which matches the SAN values in each DC&#39;s certificate.</p><h4 id="obtaining-the-enterprise-ca-certificate" tabindex="-1">Obtaining the enterprise CA certificate <a class="header-anchor" href="#obtaining-the-enterprise-ca-certificate" aria-label="Permalink to &quot;Obtaining the enterprise CA certificate&quot;">​</a></h4><p>The enterprise CA root certificate is the only certificate HPCC needs — not the individual server certs. There are several ways to obtain it:</p><p><strong>From a domain-joined Windows machine:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List trusted root CAs and export the enterprise root</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">certutil </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">store Root</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">certutil </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">exportcert </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;CA Common Name&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ca.crt</span></span></code></pre></div><p><strong>From a Linux machine joined to the domain (via sssd/realmd):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The enterprise CA cert is typically already present in the system trust store</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/ca-trust/source/anchors/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # RHEL/CentOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/share/ca-certificates/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Debian/Ubuntu</span></span></code></pre></div><p><strong>Via openssl (inspect what the server presents):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Connect to any DC and inspect its certificate chain</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dc1.corp.example.com:636</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -showcerts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div><p>The last certificate in the chain output is the CA root. Copy the <code>-----BEGIN CERTIFICATE-----</code> block to a file and use that as <code>ldapCACertFile</code>.</p><p><strong>Via your IT/PKI team</strong>: Request the root CA certificate in PEM format. If the organisation uses an intermediate CA, you may need a bundle containing both the intermediate and root.</p><h4 id="deploying-the-ca-certificate-to-hpcc-nodes" tabindex="-1">Deploying the CA certificate to HPCC nodes <a class="header-anchor" href="#deploying-the-ca-certificate-to-hpcc-nodes" aria-label="Permalink to &quot;Deploying the CA certificate to HPCC nodes&quot;">​</a></h4><p>Copy the CA cert to a stable path on each HPCC node:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enterprise-ca.crt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/hpcc/certs/ldap-ca.crt</span></span></code></pre></div><p>For Kubernetes, mount it via a <code>Secret</code> or <code>ConfigMap</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ldap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ldapTLSValidation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;strict&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ldapCACertFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/hpcc/certs/ldap-ca.crt&quot;</span></span></code></pre></div><blockquote><p><strong>Note:</strong> See the <code>ldapCACertFile</code> attribute description above for behavior when this is omitted. If the enterprise CA cert is already in the OS trust store on every node and the <code>hpcc</code> user has read access to <code>/etc/ssl/certs/</code>, <code>ldapCACertFile</code> may be omitted — but note that the platform&#39;s bundled OpenSSL may not reliably access the system trust store on all installations (see Troubleshooting).</p></blockquote><h4 id="verifying-each-pool-member-before-enabling-strict-mode" tabindex="-1">Verifying each pool member before enabling strict mode <a class="header-anchor" href="#verifying-each-pool-member-before-enabling-strict-mode" aria-label="Permalink to &quot;Verifying each pool member before enabling strict mode&quot;">​</a></h4><p>Before setting <code>ldapTLSValidation=&quot;strict&quot;</code>, verify that every pool member passes validation independently. HPCC probes all configured hosts at startup in strict and permissive modes, but you can also check manually:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify each DC in the pool</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dc1.corp.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dc2.corp.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dc3.corp.example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$dc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: &quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}:636&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -CAfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/hpcc/certs/ldap-ca.crt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Verify return&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><p>Every host should show <code>Verify return code: 0 (ok)</code>. Any that do not will surface as errors in HPCC&#39;s startup log when running in <code>permissive</code> mode, or cause startup failure in <code>strict</code> mode. Resolve each before switching to <code>strict</code>.</p><h4 id="intermediate-cas-and-certificate-bundles" tabindex="-1">Intermediate CAs and certificate bundles <a class="header-anchor" href="#intermediate-cas-and-certificate-bundles" aria-label="Permalink to &quot;Intermediate CAs and certificate bundles&quot;">​</a></h4><p>Some enterprise PKIs use an intermediate CA between the root CA and the server certificates. In this case <code>ldapCACertFile</code> must include the full chain from the intermediate up to the root, concatenated in PEM format:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Combine intermediate and root into a bundle</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> intermediate-ca.crt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root-ca.crt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ldap-ca-bundle.crt</span></span></code></pre></div><p>OpenLDAP will walk the chain from the server cert through the intermediate to the root when validating. If only the root is provided but the server cert was issued by an intermediate, validation will fail with a chain error.</p><hr><h2 id="verifying-the-configuration" tabindex="-1">Verifying the Configuration <a class="header-anchor" href="#verifying-the-configuration" aria-label="Permalink to &quot;Verifying the Configuration&quot;">​</a></h2><h3 id="confirm-the-ldap-server-is-serving-tls" tabindex="-1">Confirm the LDAP server is serving TLS <a class="header-anchor" href="#confirm-the-ldap-server-is-serving-tls" aria-label="Permalink to &quot;Confirm the LDAP server is serving TLS&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ldap-serve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:636</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -CAfile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ca-cert-fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;subject|issuer|Verify return&quot;</span></span></code></pre></div><p>A successful connection will show <code>Verify return code: 0 (ok)</code>, with <code>subject</code> showing your server certificate CN and <code>issuer</code> showing your CA. If you see a certificate error, check that the CN or SAN in the server certificate matches the hostname being connected to.</p><blockquote><p><strong>Note:</strong> <code>openssl s_client</code> without <code>&lt;/dev/null</code> will hang waiting for stdin input. Always redirect stdin to avoid this.</p></blockquote><h3 id="ldapsearch-vs-hpcc-tls-behaviour" tabindex="-1"><code>ldapsearch</code> vs. HPCC TLS behaviour <a class="header-anchor" href="#ldapsearch-vs-hpcc-tls-behaviour" aria-label="Permalink to &quot;\`ldapsearch\` vs. HPCC TLS behaviour&quot;">​</a></h3><p>On Ubuntu/Debian, the system <code>ldapsearch</code> tool is compiled against <strong>GnuTLS</strong>, while HPCC ships its own vcpkg-bundled <code>libldap</code> compiled against <strong>OpenSSL</strong>. This means they use different trust stores:</p><ul><li><strong><code>ldapsearch</code></strong> (GnuTLS): trusts only certs in the system bundle (<code>/etc/ssl/certs/ca-certificates.crt</code>). The CA certificate must be added to the system store before <code>ldapsearch</code> will accept it.</li><li><strong>HPCC</strong> (OpenSSL): trusts whatever cert file is specified by <code>ldapCACertFile</code>. The CA does <strong>not</strong> need to be in the system trust store.</li></ul><p>As a result, <code>ldapsearch</code> failing with a certificate error does not mean HPCC will fail, and vice versa. To add a CA cert to the system store for <code>ldapsearch</code> verification:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ca-cert-fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/share/ca-certificates/ldap-ca.crt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-ca-certificates</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ldapsearch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ldaps://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ldap-serve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:636</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;dc=example,dc=com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> base</span></span></code></pre></div><p>The authoritative test for HPCC is starting the platform with <code>ldapTLSValidation=&quot;strict&quot;</code> and verifying the startup log (see below).</p><h3 id="confirm-hpcc-validates-the-certificate" tabindex="-1">Confirm HPCC validates the certificate <a class="header-anchor" href="#confirm-hpcc-validates-the-certificate" aria-label="Permalink to &quot;Confirm HPCC validates the certificate&quot;">​</a></h3><p>Start the platform with <code>ldapTLSValidation=&quot;strict&quot;</code> and a correct <code>ldapCACertFile</code>. If validation fails (wrong CA cert, hostname mismatch, or expired cert), the platform will throw during startup and log the cause.</p><p>Set <code>ldapTLSValidation=&quot;permissive&quot;</code> first to diagnose issues without hard-failing, then switch to <code>strict</code> once connectivity is confirmed.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely Cause</th><th>Resolution</th></tr></thead><tbody><tr><td>Platform fails to start with TLS error</td><td><code>strict</code> mode and certificate validation cannot be enabled</td><td>Use <code>permissive</code> to diagnose; check platform logs for the specific error</td></tr><tr><td><code>Verify return code: 20</code> from openssl</td><td>CA cert not trusted</td><td>Ensure <code>ldapCACertFile</code> points to the correct CA cert</td></tr><tr><td><code>Verify return code: 62</code> from openssl</td><td>Hostname mismatch</td><td>Ensure server cert CN or SAN matches the <code>ldapAddress</code> value in config</td></tr><tr><td>Connection works in <code>permissive</code>, fails in <code>strict</code></td><td>Validation failing silently in permissive</td><td>Check platform logs for error detail</td></tr><tr><td>Works locally, fails in Kubernetes</td><td>CA cert not mounted in pod</td><td>Verify <code>ldapCACertFile</code> path exists inside the container</td></tr><tr><td>Validation chain error despite correct CA cert</td><td>Intermediate CA missing from bundle</td><td>Concatenate intermediate and root CA certs into a single PEM bundle</td></tr><tr><td>Correct cert on server but hostname mismatch</td><td>Traffic routed through SSL-terminating load balancer</td><td>The cert presented belongs to the load balancer, not the LDAP server — run <code>openssl s_client -connect &lt;ldapAddress&gt;:636 -showcerts</code> to inspect what HPCC actually sees, then use that cert&#39;s CA</td></tr><tr><td><code>ldapsearch</code> fails with cert error but HPCC works (or vice versa)</td><td>Different TLS backends — system <code>ldapsearch</code> uses GnuTLS; HPCC uses its bundled OpenSSL-linked <code>libldap</code></td><td>They use separate trust stores. Add the CA to the system store (<code>update-ca-certificates</code>) for <code>ldapsearch</code> verification; HPCC only needs <code>ldapCACertFile</code> set correctly</td></tr></tbody></table>`,82)])])}const g=e(n,[["render",r]]);export{k as __pageData,g as default};
